r"""P7 page-budget pass 3: wording-only tightening of new passages (numbers preserved or rendered elsewhere)."""
import os, re
P = os.path.expanduser("~/papers/jams-frn50k/latex/main.tex")
s = open(P).read()


def rep(old, new):
    global s
    assert s.count(old) == 1, old[:70]
    gone = sorted(set(re.findall(r"\d+(?:[.,]\d+)?", old)) - set(re.findall(r"\d+(?:[.,]\d+)?", new)))
    if gone:
        print(f"[{old[:40]}] numbers dropped: {gone}")
    s = s.replace(old, new)


rep(r"""Under A4 with $\rho\in\{0.5,1.0\}$ the generator censors almost every day and the censored-Poisson MLE does not exist in most datasets (M has no valid estimate in 77.6\%/90.5\% of attempts); on the minority with a finite MLE the comparison with naive/G is mixed (5 of 12 Holm-adjusted tests significant, in both directions). A separate controlled simulation (\S\ref{sec:controlled}) holds the expected censoring rate fixed and varies demand--capacity dependence: M keeps the smaller lift error in all six conditions, and dependence reduces that advantage ($\Theta_{0.60}=2.56$ pp). Both results describe the tested configurations, not a general correction-failure boundary, and do not establish these mechanisms for real FreshRetailNet-50K stockouts (\S\ref{sec:4-15}).""",
    r"""Under A4 with $\rho\in\{0.5,1.0\}$ almost every day is censored and the censored-Poisson MLE usually does not exist (M invalid in 77.6\%/90.5\% of attempts); where it exists, the comparison with naive/G is mixed (5 of 12 Holm-adjusted tests significant, in both directions). A controlled simulation (\S\ref{sec:controlled}) fixes the censoring rate and varies demand--capacity dependence: M keeps the smaller lift error in all six conditions, and dependence reduces that advantage ($\Theta_{0.60}=2.56$ pp). Both describe the tested configurations, not real FreshRetailNet-50K stockouts (\S\ref{sec:4-15}).""")

rep(r"""started from 10 IRLS iterations of a Poisson GLM on uncensored days and two perturbed starts (a numerical initialization only; selection into uncensored days can depend on demand, and consistency of this GLM is not established). A fit is valid only if a recession screen finds no direction of unbounded likelihood, the design is identified, and the projected gradient is at most $10^{-6}$ on both the original and the column-standardized scale; 249 of the 254 cells are valid (median 196 iterations; Appendix~\ref{app:repro}).""",
    r"""started from 10 IRLS iterations of a Poisson GLM on uncensored days and two perturbed starts (a numerical initialization only; selection into uncensored days can depend on demand). A fit is valid only if a recession screen finds no direction of unbounded likelihood, the design is identified, and the projected gradient is $\leq10^{-6}$ on the original and standardized scales; 249 of 254 cells are valid (Appendix~\ref{app:repro}).""")

rep(r"""estimated jointly by damped Newton steps on the slopes and offsets with backtracking and a joint stationarity check (slope and per-group offset scores $\leq10^{-6}$). Within a store--day only promo, depth and activity vary; the other covariates are absorbed by $\alpha$. Store--days on which every row is censored have $\hat\alpha=+\infty$ and carry no recoverable demand; they are counted, not fitted. Run on the 20 cells with the largest promotion $\times$ stockout overlap (the originally reported alternating fit is superseded; Appendix).""",
    r"""estimated jointly by damped Newton steps with a joint stationarity check ($\leq10^{-6}$); only promo, depth and activity vary within a store--day, and all-censored store--days ($\hat\alpha=+\infty$, no recoverable demand) are counted, not fitted. Run on the 20 cells with the largest promotion $\times$ stockout overlap (the earlier alternating fit is superseded; Appendix).""")

rep(r"""Under the corrected validity rule (\S\ref{sec:2-4}) the M model is valid in 249 of the 254 cells (median 196 L-BFGS iterations): cells 0$\times$8, 10$\times$4 and 17$\times$21 do not converge, 4$\times$28 is unidentified, and 14$\times$31 has no finite maximum. Every M-based statistic below is computed on these 249 cells.""",
    r"""Under the corrected validity rule (\S\ref{sec:2-4}) M is valid in 249 cells (median 196 L-BFGS iterations); 0$\times$8, 10$\times$4 and 17$\times$21 do not converge, 4$\times$28 is unidentified, and 14$\times$31 has no finite maximum. M-based statistics use these 249 cells.""")

rep(r"""The originally reported profile used a row mask that selected the wrong days for the uncensored-day hour profile; fixing it changes the peak hour of recovered demand in 160 of 254 cells and the peak hour of the gap in 178 of 254, while daily totals are unchanged.""",
    r"""The originally reported profile used a wrong uncensored-day row mask; fixing it moves the peak hour of recovered demand in 160 and of the gap in 178 of 254 cells, with daily totals unchanged.""")

rep(r"""Second, the correction is not unconditionally available or safe: in the E2 stress test, strongly non-ignorable stockout timing censors nearly every day, so the censored-Poisson estimate usually does not exist, and where it exists its error relative to naive/G is mixed (\S\ref{sec:4-15}); in the controlled simulation, demand--capacity dependence at a fixed censoring rate reduces M's lift-error advantage without reversing it (\S\ref{sec:controlled}).""",
    r"""Second, the correction is not unconditionally available or safe: in E2, strongly non-ignorable stockouts censor nearly every day, so the censored-Poisson estimate usually does not exist, and where it exists its error relative to naive/G is mixed (\S\ref{sec:4-15}); at a fixed censoring rate, dependence reduces M's lift-error advantage without reversing it (\S\ref{sec:controlled}).""")

rep(r"""Non-existence, not finite-sample error of a computed estimate, is the demonstrated failure mode. The earlier solver had flagged 4,352 of the 4,526 non-existence datasets as converged, which produced the large error medians and the 10 of 12 significant tests reported before this correction; on identical repeat IDs the earlier and corrected estimates agree, so the change comes from failure accounting.""",
    r"""Non-existence, not finite-sample error of a computed estimate, is the demonstrated failure mode. The earlier solver flagged 4,352 of the 4,526 non-existence datasets as converged, producing the large error medians and the 10 of 12 significant tests reported before this correction; on identical repeat IDs earlier and corrected estimates agree.""")

rep(r"""In E2 the shared shock raises the censoring rate together with the dependence, so A4 ends in near-total censoring. A separate, fully synthetic experiment (fixed protocol, version 1.0; no FreshRetailNet-50K data) holds the expected censoring rate fixed and varies the dependence.""",
    r"""In E2 the shared shock raises censoring together with dependence. A separate, fully synthetic experiment (fixed protocol, version 1.0; no FreshRetailNet-50K data) holds the expected censoring rate fixed and varies the dependence.""")

FE_A = r"""\textbf{Correction note.} The originally reported F results came from an alternating algorithm whose censored-row curvature had the wrong sign and which had no joint convergence check; in 5 of the 20 cells the offset step stopped after one iteration and was reported as non-converged. Those results (15/20 converged; median ratio 1.274; e.g.\ cell 0$\times$5 recovered F 217.8 and cell 0$\times$28 $-528.6$) are superseded. The corrected joint Newton fit is valid in all 20 cells (6--10 iterations, joint stationarity $\leq10^{-6}$). Only promo, depth and activity vary within a store--day; the other covariates are absorbed by the offsets. Store--days on which every row is censored (111--9,653 per cell) have an infinite offset and carry no recoverable demand; their rows are excluded from both naive B and recovered F. On this basis cell 0$\times$5 gives recovered F 10.48 vs.\ naive 9.13, and cell 0$\times$28 $-14.06$ vs.\ $-5.40$; the median $|bias_{\text{B}}|/|naive_{\text{B}}|$ is 0.600 (0.071--4.048). The headline still rests on M, with F as a sensitivity check."""
rep(FE_A, r"""\textbf{Correction note.} The originally reported F results came from an alternating algorithm with a wrong-signed censored-row curvature and no joint convergence check (5 of 20 cells stopped after one iteration). Those results (15/20 converged; median ratio 1.274; cell 0$\times$5 recovered F 217.8, cell 0$\times$28 $-528.6$) are superseded. The corrected joint Newton fit is valid in all 20 cells (6--10 iterations). Store--days with every row censored (111--9,653 per cell) have an infinite offset and no recoverable demand; their rows are excluded from naive B and recovered F. Cell 0$\times$5 now gives recovered F 10.48 vs.\ naive 9.13, cell 0$\times$28 $-14.06$ vs.\ $-5.40$; median $|bias_{\text{B}}|/|naive_{\text{B}}|$ 0.600 (0.071--4.048). The headline rests on M, with F as a sensitivity check.""")

